-- Generated by `chainindex dbt` from chains/base.yaml and abis/AerodromeCLFactory.json. Do not edit: change the chain file or ABI and regenerate.
-- SwapFeeModuleChanged(address,address)
{{ config(
    materialized='view',
    schema='events_base',
    alias='aerodrome_cl_factory__swap_fee_module_changed',
    tags=['chains', 'chain_base'],
) }}

select
    toUInt64(8453) as chain_id,
    address,
    block_number,
    block_time,
    block_hash,
    transaction_hash,
    transaction_index,
    log_index,
    inserted_at,
    concat('0x', substring(substring(topic1, 3, 64), 25, 40)) as old_fee_module,
    concat('0x', substring(substring(topic2, 3, 64), 25, 40)) as new_fee_module
from {{ source('chain_base', 'logs') }}
where topic0 = '0xdf24ed64a7bcd761cf1132e79f94ea269a1d570e7a6ca0ab99a8f5ccd6f5022f'
  and address in (select address from {{ ref('base__contracts') }} where contract = 'aerodrome_cl_factory')
  and (block_number, block_hash) not in (
    select block_number, block_hash from {{ source('chain_base', 'orphaned_blocks') }}
  )
